import org.apache.kafka.clients.admin.AdminClient; import org.apache.kafka.clients.admin.AdminClientConfig; import org.apache.kafka.common.Node; import java.util.Properties; import java.util.Collection; public class TestKafka { public static void main(String[] args) throws Exception { Properties props = new Properties(); props.put(AdminClientConfig.BOOTSTRAP_SERVERS_CONFIG, "192.168.3.222:9095"); props.put(AdminClientConfig.REQUEST_TIMEOUT_MS_CONFIG, "5000"); try (AdminClient client = AdminClient.create(props)) { System.out.println("Connecting..."); Collection<Node> nodes = client.describeCluster().nodes().get(); for(Node n : nodes) { System.out.println("Node: " + n.host() + ":" + n.port()); } } } }
